SELECT , d.min_amount, d.max_amount, d.min_month, d.max_month, MIN(br.base_rate_percent) AS min_base_rate_percent, MAX(br.max_rate_percent) AS max_rate_percent FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN deposit d ON d.kb_product_version_id = pv.kb_product_version_id LEFT JOIN base_interest_rate br ON br.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
GROUP BY pv.kb_product_version_id, pv.kb_product_data_version_id, p.product_id, p.product_code, pv.product_name, p.product_type, pv.description, pv.product_url, pv.sales_status, pv.created_at, d.min_amount, d.max_amount, d.min_month, d.max_month ORDER BY pv.product_name

SELECT , s.savings_category, s.monthly_min_amount, s.monthly_max_amount, s.min_month, s.max_month, MIN(br.base_rate_percent) AS min_base_rate_percent, MAX(br.max_rate_percent) AS max_rate_percent FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN savings s ON s.kb_product_version_id = pv.kb_product_version_id LEFT JOIN base_interest_rate br ON br.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
GROUP BY pv.kb_product_version_id, pv.kb_product_data_version_id, p.product_id, p.product_code, pv.product_name, p.product_type, pv.description, pv.product_url, pv.sales_status, pv.created_at, s.savings_category, s.monthly_min_amount, s.monthly_max_amount, s.min_month, s.max_month ORDER BY pv.product_name

SELECT , e.stock_code, e.etf_category, e.tracking_index, e.annual_return_5y AS annual_return_5y_percent, e.bond_ratio AS bond_ratio_percent, e.risk_level FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN etf e ON e.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
ORDER BY pv.product_name

